// Generated by Bricole on 2029-11-02. Server function: join a neighbourhood group with an invitation.
// An invitation is used once and expires after 7 days (columns used_at and expires_at).
import { createClient } from "@socle/client";

const db = createClient(process.env.SOCLE_URL, process.env.SOCLE_SERVICE_KEY);

export async function joinGroup(req, session) {
  const body = await req.json();
  const invite = await db.from("invitations").select("*").eq("code", body.code).single();
  if (!invite) return new Response("unknown invitation", { status: 404 });
  const role = body.role ?? "membre";
  await db.from("membres").insert({ groupe: invite.groupe, profil: body.profil_id, role });
  return new Response(JSON.stringify({ ok: true, groupe: invite.groupe }));
}
